let hidBuffer='',hidLastAt=0,hidTimer=null;document.addEventListener('keydown',e=>{if(page!=='Sales & POS'||e.ctrlKey||e.altKey||e.metaKey)return;const target=e.target;if(target&&(['INPUT','TEXTAREA','SELECT'].includes(target.tagName)||target.isContentEditable))return;const now=performance.now();if(e.key==='Enter'){if(hidBuffer.length>=4){e.preventDefault();lookupBarcode(hidBuffer)}hidBuffer='';hidLastAt=0;return}if(e.key.length===1){if(hidLastAt&&now-hidLastAt>90)hidBuffer='';hidBuffer+=e.key;hidLastAt=now;clearTimeout(hidTimer);hidTimer=setTimeout(()=>{hidBuffer='';hidLastAt=0},350)}});document.addEventListener('click',e=>{let n=e.target.closest('[data-page]');if(n)return go(n.dataset.page);let b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b.dataset.id)});$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#search').onkeydown=e=>{if(e.key==='Enter'){let q=e.target.value.toLowerCase();if(products.some(p=>(p.name+' '+p.sku).toLowerCase().includes(q)))go('Products');else if(q.includes('sale')||q.includes('order'))go('Sales & POS');else toast('No matching demo result')}};if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});render();
